<script setup lang="ts">
import {computed,onMounted,ref,watch} from 'vue'
import {scheduleApi} from '../schedules'
const props=defineProps<{homeworkId:number;assignments:any[]}>()
const emit=defineEmits<{busy:[value:boolean];dirty:[value:boolean]}>()
const columns=computed(()=>[...props.assignments].sort((a,b)=>a.assigned_on.localeCompare(b.assigned_on)||a.id-b.id))
const rows=ref<any[]>([]),loading=ref(false),saving=ref(false),error=ref(''),message=ref(''),search=ref('')
const statuses=[['pending','Unmarked'],['submitted','O - Done'],['missing','X - Not done'],['late','- Late submission'],['reviewed','O - Reviewed']]
const mark=(s:string)=>s==='submitted'||s==='reviewed'?'O':s==='missing'?'X':s==='late'?'-':'.'
const visible=computed(()=>rows.value.filter(s=>(s.full_name+' '+s.login_id).toLowerCase().includes(search.value.toLowerCase().trim())))
const changed=computed(()=>rows.value.flatMap(s=>Object.entries(s.marks).filter(([,m]:any)=>m.status!==m.saved)))
watch(changed,()=>emit('dirty',changed.value.length>0),{deep:true})
async function load(){loading.value=true;error.value='';try{const results=await Promise.all(columns.value.map(h=>scheduleApi(`teacher/homework/${h.id}/progress`)));const students=new Map<number,any>();results.forEach((r,i)=>r.students.forEach((s:any)=>{if(!students.has(s.id))students.set(s.id,{id:s.id,full_name:s.full_name,login_id:s.login_id,marks:{}});students.get(s.id).marks[columns.value[i]!.id]={status:s.status,saved:s.status,version:s.version}}));rows.value=[...students.values()]}catch(e){error.value=e instanceof Error?e.message:'Unable to load register.'}finally{loading.value=false}}
async function refresh(){if(changed.value.length&&!window.confirm('Discard unsaved updates?'))return;await load()}
async function saveAll(){saving.value=true;emit('busy',true);error.value='';message.value='';try{for(const h of columns.value){const records=rows.value.filter(s=>s.marks[h.id]&&s.marks[h.id].status!==s.marks[h.id].saved).map(s=>({student_user_id:s.id,status:s.marks[h.id].status,version:s.marks[h.id].version}));if(!records.length)continue;const result=await scheduleApi(`teacher/homework/${h.id}/progress`,'PUT',{records});for(const m of result.records){const cell=rows.value.find(s=>s.id===m.student_user_id).marks[h.id];Object.assign(cell,{saved:m.status,status:m.status,version:m.version})}}message.value='All updates saved.'}catch(e){error.value=(e instanceof Error?e.message:'Unable to save.')+' Earlier saved columns remain saved; unsaved cells are kept for review.'}finally{saving.value=false;emit('busy',false)}}
onMounted(load)
</script>
<template><section class="homework-tracking"><p class="muted">O = Done · X = Not done · - = Late submission · . = Unmarked. Columns show assigned dates, not calendar days. Separate homework on the same date has its own column.</p><p v-if="loading" role="status">Loading register…</p><p v-if="error" role="alert" class="error">{{error}}</p><p v-if="message" role="status">{{message}}</p><div class="tracking-filters"><label>Find a student<input v-model="search" type="search" placeholder="Name or student ID"></label><button class="secondary" :disabled="loading||saving" @click="refresh">Refresh</button></div><div class="tracking-table-scroll"><table class="tracking-table"><thead><tr><th scope="col">Student</th><th v-for="h in columns" :key="h.id" scope="col"><time>{{h.assigned_on}}</time><small>{{h.title}}</small><small>Due {{h.due_on}}</small></th></tr></thead><tbody><tr v-for="s in visible" :key="s.id"><th scope="row"><strong>{{s.full_name}}</strong><small>{{s.login_id}}</small></th><td v-for="h in columns" :key="h.id"><label v-if="s.marks[h.id]"><span class="tracking-sr">{{s.full_name}}: {{h.title}} assigned {{h.assigned_on}}</span><select v-model="s.marks[h.id].status" :disabled="saving" :class="s.marks[h.id].status"><option v-for="[value,label] in statuses" :key="value" :value="value">{{label}}</option></select><small>{{mark(s.marks[h.id].saved)}} saved{{s.marks[h.id].status!==s.marks[h.id].saved?' · Unsaved':''}}</small></label><span v-else>Not in roster</span></td></tr></tbody></table></div><p v-if="!loading&&!visible.length">No students match.</p><div class="tracking-savebar"><span role="status">{{changed.length}} unsaved update(s), including hidden rows</span><button :disabled="loading||saving||!changed.length" @click="saveAll">{{saving?'Saving…':'Save all changes'}}</button></div></section></template>
<style scoped>
.tracking-summary{display:flex;flex-wrap:wrap;gap:8px;margin:16px 0}.tracking-summary span{background:#eef4f0;padding:8px 10px;border-radius:8px;font-size:13px}.tracking-filters{display:flex;align-items:end;flex-wrap:wrap;gap:12px}.tracking-filters label{flex:1;min-width:140px}.homework-tracking input,.homework-tracking select{width:100%;font:inherit;font-size:16px;padding:10px;border:1px solid #bccfc5;border-radius:8px;background:white;color:#243e33}.homework-tracking label{margin:0}.homework-tracking button{width:auto;margin:0;min-height:44px;padding:10px 14px;font-size:14px}.tracking-student{display:grid;grid-template-columns:minmax(0,1fr) 160px;align-items:center;gap:12px;padding:14px 0;border-bottom:1px solid #dce5df;font-size:15px}.tracking-student small{display:block;color:#60736e;font-size:12px;margin-top:4px}.tracking-savebar{position:sticky;bottom:0;display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:12px;padding:14px 0 4px;margin-top:12px;background:#fff;border-top:1px solid #dce5df}.tracking-savebar span{font-size:12px;color:#60736e}.tracking-sr{position:absolute;width:1px;height:1px;overflow:hidden;clip-path:inset(50%)}@media(max-width:480px){.tracking-student{grid-template-columns:minmax(0,1fr) auto;gap:8px}.tracking-student>div{grid-column:1/-1}.tracking-student label{width:100%}}
.tracking-table-scroll{max-height:530px;overflow:auto;margin-top:16px;border:1px solid #dce5df;border-radius:10px}.tracking-table{width:100%;border-collapse:collapse;text-align:left;font-size:14px}.tracking-table th,.tracking-table td{padding:10px 12px;border-bottom:1px solid #dce5df}.tracking-table thead th{position:sticky;top:0;background:#eef4f0;z-index:1}.tracking-table tbody th{font-weight:400;min-width:140px}.tracking-table small{display:block;font-size:12px;color:#60736e;margin-top:4px}.tracking-table select{min-width:170px;min-height:44px}.tracking-mark{font-size:20px;font-weight:700}.tracking-mark.submitted,.tracking-mark.reviewed{color:#185b38}.tracking-mark.missing{color:#a22f24}.tracking-mark.late{color:#805c12}</style>
